 83 |         if (claimable == 0) revert NoFeesToClaim();
 84 |         tokensData[token].unclaimedFees[msg.sender] = 0;
 85 |         payable(msg.sender).transfer(claimable);
 86 |         emit FeesClaimed(token, msg.sender, claimable);
 87 |     }
